public class Factorial {

    // Correct recursive factorial method
    public static int factorial(int n) {
        // Base case: matches requirements (0! = 1 AND 1! = 1)
        if (n == 0 || n == 1) {
            return 1;
        }
        // Recursive case: n! = n * (n-1)! (reduces n, stops infinite recursion)
        return n * factorial(n - 1);
