```java
public int findMaxConsecutive(int[] arr) {
    // Edge case: empty array has 0 consecutive elements
    if (arr.length == 0) {
        return 0;
    }

    // Initialize: a non-empty array has at least 1 element (minimum sequence length = 1)
    int maxCount = 1;
    int currentCount = 1;

    // Loop: compare current element (i) with NEXT element (i+1)
    // Run until i < arr.length-1, to avoid out-of-bounds (i+1 is always valid)
    for (int i = 0; i < arr.length - 1; i++) {
        if (arr[i] == arr[i + 1]) {
            // Elements match: extend current sequence
            currentCount++;
        } else {
            // Elements do NOT match: reset current sequence length
            currentCount = 1;
        }

        // Update maxCount if current sequence is longer
        if (currentCount > maxCount) {
            maxCount = currentCount;
        }
    }

    return maxCount;
}
```


