                    // Check for duplicate mandatory queens in the same row
                    if (mandatoryColPerRow[i] != -1) {
                        return 0; // Multiple mandatory queens per row: invalid
                    }
                    mandatoryColPerRow[i] = j;
                    countMandatory++;
                }
            }
        }
        // Step 2: Pre-validate mandatory queens have no conflicts
        boolean[] usedCols = new boolean[n];
        boolean[] usedMainDiag = new boolean[2 * n - 1]; // row - col + 7 = index
        boolean[] usedAntiDiag = new boolean[2 * n - 1]; // row + col = index
        for (int row = 0; row < n; row++) {
            int col = mandatoryColPerRow[row];
            if (col == -1) continue;
            // Check if column/diagonals are already used by another mandatory queen
            int mainDiagIdx = row - col + 7;
            int antiDiagIdx = row + col;
            if (usedCols[col] || usedMainDiag[mainDiagIdx] || usedAntiDiag[antiDiagIdx]) {
                return 0; // Mandatory queens conflict: no solutions
            }
            usedCols[col] = true;
            usedMainDiag[mainDiagIdx] = true;
            usedAntiDiag[antiDiagIdx] = true;
        }
        // Step 3: Start backtracking with correct initial state
        int queensLeftToPlace = 8 - countMandatory;
        return backtrack(0, board, mandatoryColPerRow, usedCols, usedMainDiag, usedAntiDiag, queensLeftToPlace);
    }
    private int backtrack(int row, int[][] board, int[] mandatoryColPerRow,
                          boolean[] usedCols, boolean[] usedMainDiag, boolean[] usedAntiDiag,
                          int queensLeft) {
        int n = 8;
        // Base case: processed all rows
        if (row == n) {
            return queensLeft == 0 ? 1 : 0; // Ensure we placed exactly enough queens
        }
        // Case 1: This row has a mandatory queen - no choice, proceed to next row
        if (mandatoryColPerRow[row] != -1) {
            // Mandatory queen was already validated in preprocessing, no need to recheck
            return backtrack(row + 1, board, mandatoryColPerRow, usedCols, usedMainDiag, usedAntiDiag, queensLeft);
        }
        // Case 2: No mandatory queen - need to place exactly one here
        int count = 0;
        for (int col = 0; col < n; col++) {
            // Skip blocked squares or squares with mandatory queens (none in this row, but safety check)
            if (board[row][col] == -1 || board[row][col] == 1) {
                continue;
            }
            // Calculate diagonal indices
            int mainDiagIdx = row - col + 7;
            int antiDiagIdx = row + col;
            // Check for conflicts
            if (!usedCols[col] && !usedMainDiag[mainDiagIdx] && !usedAntiDiag[antiDiagIdx]) {
                // Mark column and diagonals as used
                usedCols[col] = true;
                usedMainDiag[mainDiagIdx] = true;
                usedAntiDiag[antiDiagIdx] = true;
                // Recurse
                count += backtrack(row + 1, board, mandatoryColPerRow, usedCols, usedMainDiag, usedAntiDiag, queensLeft - 1);
                // Backtrack - unmark
                usedCols[col] = false;
                usedMainDiag[mainDiagIdx] = false;
                usedAntiDiag[antiDiagIdx] = false;
            }
        }
        return count;
    }
}
```
